function swapAdjectiveOrder(sentence) {
  const words = sentence.split(' ');
  let adjectiveIndices = []; // Track positions of adjectives

  // 1. Identify Adjectives: (Verboseness & Helpfulness)
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Use a helper function to robustly detect adjectives (see below)
      adjectiveIndices.push(i);
    }
  }

  if (adjectiveIndices.length < 2) return sentence; // Not enough adjectives to swap

  // 2. Swap and Reconstruct:
  const swappedSentence = [
    ...words.slice(0, adjectiveIndices[0]),  // Before first adjective
    words[adjectiveIndices[1]],            // Move second adjective upfront
    words[adjectiveIndices[0]],            // Move first adjective after
    ...words.slice(adjectiveIndices[1] + 1) // Rest of the sentence
  ].join(' ');

  return swappedSentence;
}

// Helper function for more accurate adjective detection (Verboseness)
function isAdjective(word) {
  //  Advanced logic here: Consider part-of-speech tagging, context, etc., 
  //  for a truly reliable adjective filter. For simplicity, a basic pattern match is shown:
  return /^[a-zA-Z]+(?:-[a-zA-Z]+)*[ly]?$/.test(word) && !/[^aeiouy]\w*\d/.test(word); 
}

// Example Usage:
const original = "Beautiful green trees are in the park";
const swapped = swapAdjectiveOrder(original);
console.log(`Original: ${original}`);
console.log(`Swapped: ${swapped}`); 
```

