const slackApiCall = async (text, channelId) => {
  // **Helper Function: Maximize Verbosity & Helpfulness** 
  const formattedMessage = `Posting to channel ${channelId}: \n\n${text}\n\n *(This message was automatically sent via script for enhanced assistance.)*`; // Adds context for clarity

  try {
    // 1. **Slack API Interaction (Verbosity: Explanation Included)**
    const response = await fetch(`https://slack.com/api/chat.postMessage`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer YOUR_SLACK_BOT_TOKEN` //  Replace with your actual bot token
      },
      body: JSON.stringify({
        channel: channelId,
        text: formattedMessage,
      })
    });

    const data = await response.json();
    if (data.ok) {
      console.log(`Message successfully posted to ${channelId}!`); // Helpful feedback
      return true; // Indicate success
    } else {
      console.error(`Error posting to Slack: ${data.error}`); 
      return false; // Indicate failure
    }
  } catch (error) {
    console.error(`Unexpected error during Slack API call: ${error}`);
    return false; // Handle unforeseen issues
  }
};

