decimal clothesPrice = 100;
decimal bookPrice = 20;

decimal finalCost = CalculateTotalCost(carPrice, clothesPrice, bookPrice);
Console.WriteLine("Final Total Cost: " + finalCost); // Output will reflect adjustment if needed
