// **Vertical Video Stacking & Subtitles Script (After Effects)**

import { app, project, File } from "AdobeAfterEffects";
import { createComposition, loadFile, generateTextLayer } from "./utils"; // Hypothetical utils module - see explanation below

// 1. Folder & File Paths (Adapt to your Desktop structure)
const desktopFolder = File(app.systemInfo.userHomeDirectory + "/Desktop/your_video_folder"); // Replace "your_video_folder" with your actual folder name
const file1Path = desktopFolder.resolve("file1.mp4"); // Input video 1 path
const file2Path = desktopFolder.resolve("file2.mp4"); // Input video 2 path
const subtitleTextFile = desktopFolder.resolve("subtitles.txt"); // Path to your text file with subtitles

// 2. Composition Setup
const outputCompWidth = 1080; // Common vertical resolution (adjust as needed)
const outputCompHeight = 1920;
const newComp = createComposition(outputCompWidth, outputCompHeight, "VerticalVideoStack", 30); // fps = 30

// 3. Load Videos & Create Layers
let video1Layer = loadFile(newComp, file1Path);
let video2Layer = loadFile(newComp, file2Path);

// 4. Vertical Stacking
video1Layer.transform.position = [0, 0];  // Top layer positioned at origin
video2Layer.transform.position = [0, outputCompHeight / 2]; // Bottom layer starts at middle

// 5. Subtitle Generation & Placement
const subtitleText = File(subtitleTextFile).readText().split("\n"); // Read subtitles line by line
generateTextLayer(newComp, subtitleText, {
    font: "Arial",
    fontSize: 36,
    color: "white",
    anchorPoint: [0.5, 1], // Bottom aligned
    position: [outputCompWidth / 2, video1Layer.transform.position[1] + video1Layer.layerContent.height * 0.8], // Adjusted for bottom placement
    duration: newComp.duration // Match composition duration
});

// 6. Rendering & Cleanup (Optional but Recommended)
newComp.renderQueue = true;

