import Foundation

func generateSportComparison(sportPreference: String) -> [[String]] {
    var comparisonData: [[String]] = [] // Our Excel-table structure

    // Header Row (Fixed)
    comparisonData.append(["Factor", "Skiing", "Snowboarding"])

    // Data Population using Conditional Logic & Formatting
    let factors = [
        "Speed": sportPreference == "skiing" ? "High (greater linear speed)" : "Moderate to High (carving dependent)",
        "Difficulty": sportPreference == "skiing" ? "Generally moderate initial learning curve" : "Steeper initial learning curve",
        "Style": sportPreference == "skiing" ? "Classic, graceful, versatile" : "Fluid, freeride-focused, expressive",
        "Learning Curve": sportPreference == "skiing" ? "Relatively quicker basics, advanced techniques take time" : "Initially challenging, mastering tricks accelerates progress",
        "Terrain Variety": sportPreference == "skiing" ? "Excellent adaptability to groomed runs, backcountry, parks" : "Strong in powder, parks, excels off-piste",
        "Trick Opportunities": sportPreference == "skiing" ? "Possible but more specialized disciplines" : "Highly conducive to freestyle and tricks"
    ]

    // Populate Rows with Formatted Values
    for (factor, description) in factors {
        comparisonData.append([factor, description])
    }

    return comparisonData
}

