using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json; // Assuming JSON serialization/deserialization

public class RestServiceWrapper<T> where T : class
{
    private readonly HttpClient _httpClient;
    private readonly string _baseUrl;
    private string _authToken;

    public RestServiceWrapper(string baseUrl, string initialAuthToken = null)
    {
        _baseUrl = baseUrl;
        _authToken = initialAuthToken;
        _httpClient = new HttpClient { BaseAddress = new Uri(_baseUrl) };
        // Add optional handlers for automatic authentication renewal, logging, etc. here
    }

    protected async Task<HttpResponseMessage> MakeRequestAsync(HttpMethod method, string relativeUrl, object content = null, Dictionary<string, string> headers = null)
    {
        headers ??= new Dictionary<string, string>();
        headers["Authorization"] = $"Bearer {_authToken}"; // Attach auth token

        var request = new HttpRequestMessage(method, relativeUrl)
        {
            Content = content == null ? null : new StringContent(JsonConvert.SerializeObject(content), System.Text.Encoding.UTF8, "application/json"),
            Headers = {AddRange(headers) } // Merge custom headers
        };

        return await _httpClient.SendAsync(request);
    }

    // Generic methods for common REST operations (expand as needed)
    public async Task<T> GetAsync(string relativeUrl, params KeyValuePair<string, string>[] queryParameters)
    {
        var uriBuilder = new UriBuilder(_baseUrl + relativeUrl);
        foreach (var param in queryParameters)
            uriBuilder.Query += $"{param.Key}={param.Value}&"; // Build query string

        HttpResponseMessage response = await MakeRequestAsync(HttpMethod.Get, uriBuilder.ToString());
        return await HandleResponse<T>(response);
    }

    public async Task<T> PostAsync<TRequest>(string relativeUrl, TRequest data)
    {
        return await MakeRequestAsync(HttpMethod.Post, relativeUrl, data, null)
