import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { Role } from './user.entity'; // Assuming User entity has a Role enum

const PERMISSIONS = [
  'READ_USERS',
  'CREATE_USERS',
  'UPDATE_USERS',
  'DELETE_USERS',
  'READ_PRODUCTS',
  'CREATE_PRODUCTS',
  'UPDATE_PRODUCTS',
  'DELETE_PRODUCTS',
  // ... add more permissions as needed
];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles restriction

    const request = context.switchToHttp().getRequest();
    const user = request.user; // Assuming user info is available in request

    if (!user || !user.role) throw new UnauthorizedException();

    const userHasPermissions = await this.prisma.user.findUnique({
      where: { id: user.id },
      select: { roles: true },
    }).then(user => user?.roles?.some(r => requiredRoles.includes(r)));

    return userHasPermissions && this.permissionCheck(user.role, requiredRoles);
  }

  permissionCheck(userRole: Role, requiredRoles: Role[]): boolean {
    // Logic to map Role enum to permission checks against PERMISSIONS array
    //  Return true if userRole grants access based on requiredRoles and PERMISSIONS
    //  Example (simplified):
    switch (userRole) {
      case Role.ADMIN: return true; // Admin has all permissions
      case Role.EDITOR: return requiredRoles.every(r => PERMISSIONS.includes(r)); 
      // ... handle other roles and specific permission mappings
      default: return false;
    }
  }
}
```

**Explanation (within the constraints):**

1. **`PERMISSIONS` Array:**  Defines a central list of permission

