/**
 * Searches for a place name in a specified column and retrieves latitude and longitude, storing them in designated columns.
 *
 * @param {string} sheetName Spreadsheet sheet name containing the data.
 * @param {number} placeNameColumn Index (starting from 0) of the column with place names.
 * @param {number} latColumn Index (starting from 0) for storing latitude results.
 * @param {number} lngColumn Index (starting from 0) for storing longitude results.
 * @param {string} apiKey Your Google Maps Geocoding API key (obtain from https://developers.google.com/maps/documentation/geocoding/get-api-key)
 */
function geocodePlaceNames(sheetName, placeNameColumn, latColumn, lngColumn, apiKey) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const lastRow = sheet.getLastRow(); // Find the last populated row

  // Iterate through each row containing a place name
  for (let row = 2; row <= lastRow; row++) { // Start from row 2 (assuming header row is row 1)
    const placeName = sheet.getRange(row, placeNameColumn).getValue();
    if (placeName) { // Only process if there's a place name
      const geocoder = new google.maps.Geocoder();
      geocoder.geocode({ address: placeName }, (results, status) => {
        if (status === google.maps.GeocoderStatus.OK) {
          const latitude = results[0].geometry.location.lat();
          const longitude = results[0].geometry.location.lng();
          sheet.getRange(row, latColumn).setValue(latitude);
          sheet.getRange(row, lngColumn).setValue(longitude);
          Logger.log(`Successfully geocoded "${placeName}" - Lat: ${latitude}, Lng: ${longitude}`);
        } else {
          Logger.log(`Error geocoding "${placeName}": ${status}`);
          // Handle geocoding errors (e.g., invalid address, API limit reached)
          //  You might want to log errors to a separate sheet or display warnings.
        }
      });
    }
  }
}
